/*
 * A071033  a(n) = n-th state of cellular automaton generated by "Rule 94"
 *          when started with a single ON cell.
 * https://oeis.org/A071033
 *
 * Offset:    0    (a(0) is the first term)
 * Keywords:  nonn, easy
 * Formula:   not stated
 * Range:     u8 n <= 1, u16 n <= 2, u32 n <= 4, u64 n <= 9, u128 n <= 19,
 *            big any n
 * Helpers:   none
 *
 * Sequence data from the OEIS (https://oeis.org), licensed CC BY-SA 4.0.
 */

/* Rule 94 cellular automaton starting from a single ON cell.
   The state at time n has length 2*n+1; this function builds the
   decimal number whose digits are the state bits (1 and 0). */

#include <stddef.h>

seq_t a(idx_t n)
{
    /* Length of the state */
    size_t len = (size_t)(2 * n + 1);

    seq_t res = 0;

    if ((n & 1) == 0)    /* even n */
    {
        for (idx_t i = 0; i < (idx_t)len; ++i)
        {
            int digit;
            if (i < 2 || i >= (idx_t)len - 2)
                digit = 1;
            else
                digit = ((i - 2) & 1) ? 1 : 0;   /* 0,1,0,1... */
            res = res * 10 + (seq_t)digit;
        }
    }
    else                 /* odd n */
    {
        for (idx_t i = 0; i < (idx_t)len; ++i)
        {
            int digit;
            if (i < 3 || i >= (idx_t)len - 3)
                digit = 1;
            else
                digit = ((i - 3) & 1) ? 1 : 0;   /* 0,1,0,1... */
            res = res * 10 + (seq_t)digit;
        }
    }

    return res;
}
